import { cva } from 'class-variance-authority';
import { type ClassValue, clsx } from 'clsx';
import type React from 'react';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function wrapStringChild(
  child: React.ReactNode,
  Wrapper: React.ComponentType<{
    children: React.ReactNode;
    className?: string | undefined;
  }>,
  className?: string
): React.ReactNode {
  if (typeof child === 'string') {
    return <Wrapper className={className}>{child}</Wrapper>;
  }
  return child;
}

export interface SharedProps {
  'data-testid'?: string | undefined;
  testId?: string | undefined;
}

export interface PortalRootProps {
  defaultOpen?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  open?: boolean | undefined;
}

export type ModalRootProps = PortalRootProps & {
  modal?: boolean | undefined;
};

export interface FocusScopeContentProps {
  onCloseAutoFocus?: ((event: Event) => void) | undefined;
  onOpenAutoFocus?: ((event: Event) => void) | undefined;
}

export type PortalContentProps = FocusScopeContentProps & {
  container?: HTMLElement | undefined;
};

export type FixedPositionContentProps = PortalContentProps & {
  showOverlay?: boolean;
};

export type SemanticVariant = 'success' | 'info' | 'warning' | 'error' | 'disabled';
export type DotSize = 'xxs' | 'xs' | 'sm' | 'md' | 'lg';
export interface StackableProps {
  stacked?: boolean;
}

export const dotColorVariants = cva('', {
  defaultVariants: {
    variant: 'info',
  },
  variants: {
    variant: {
      disabled: 'bg-muted',
      error: 'bg-destructive',
      info: 'bg-primary',
      success: 'bg-primary',
      warning: 'bg-primary',
    },
  },
});

export const dotStackedVariants = cva('!border-background', {
  defaultVariants: {
    size: 'md',
  },
  variants: {
    size: {
      lg: 'border-2',
      md: 'border-2',
      sm: 'border',
      xs: 'border-2',
      xxs: 'border',
    },
  },
});

import { cva } from 'class-variance-authority';

export const alertVariants = cva(
  'group/alert relative grid w-full grid-cols-[0_minmax(0,1fr)] items-start gap-y-0.5 rounded-lg border px-4 py-3 text-sm has-data-[slot=alert-action]:pr-18 has-[>svg]:grid-cols-[calc(var(--spacing)*4)_minmax(0,1fr)] has-[>svg]:gap-x-3 [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current',
  {
    defaultVariants: {
      variant: 'info',
    },
    variants: {
      variant: {
        default: 'bg-card text-card-foreground',
        destructive:
          '!border-destructive/20 bg-destructive/10 text-destructive *:data-[slot=alert-description]:text-destructive/90 [&>href]:text-current [&>svg]:text-current',
        info: 'bg-card text-card-foreground',
        success: 'border-primary/20 bg-primary/5 text-foreground [&>svg]:text-primary',
        warning: 'border-primary/20 bg-muted text-foreground [&>svg]:text-primary',
      },
    },
  }
);

import type { VariantProps } from 'class-variance-authority';
import { InfoIcon } from 'lucide-react';
import type React from 'react';
import { alertVariants } from '@/components/ui/shared/alert-variants';
import { cn } from '@/registry/base-nova/protoform/lib/utils';
import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

const DEFAULT_ALERT_ICON = <InfoIcon />;
const Alert = ({
  className,
  variant,
  testId,
  icon = DEFAULT_ALERT_ICON,
  children,
  ref,
  ...props
}: React.ComponentProps<'div'> &
  VariantProps<typeof alertVariants> &
  SharedProps & { icon?: React.ReactNode } & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    className={cn(alertVariants({ variant }), className)}
    data-slot="alert"
    data-testid={testId}
    ref={ref}
    role="alert"
    {...props}
  >
    {icon}
    {children}
  </div>
);
Alert.displayName = 'Alert';
const AlertTitle = ({
  className,
  testId,
  ref,
  ...props
}: React.ComponentProps<'div'> & SharedProps & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    className={cn(
      'col-start-2 line-clamp-1 min-h-4 font-medium tracking-tight group-has-data-[slot=alert-action]/alert:line-clamp-none',
      className
    )}
    data-slot="alert-title"
    data-testid={testId}
    ref={ref}
    {...props}
  />
);
AlertTitle.displayName = 'AlertTitle';
const AlertDescription = ({
  className,
  testId,
  ref,
  ...props
}: React.ComponentProps<'div'> & SharedProps & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    className={cn(
      'col-start-2 grid w-full min-w-0 justify-items-start gap-1 text-sm wrap-anywhere text-muted-foreground [&_p]:leading-relaxed [&_pre]:w-full',
      className
    )}
    data-slot="alert-description"
    data-testid={testId}
    ref={ref}
    {...props}
  />
);
AlertDescription.displayName = 'AlertDescription';
function AlertAction({ className, ...props }: React.ComponentProps<'div'>) {
  return <div className={cn('absolute top-2 right-2', className)} data-slot="alert-action" {...props} />;
}

export { Alert, AlertAction, AlertDescription, AlertTitle };

'use client';

import type { CSSProperties } from 'react';

import { cn } from '@/registry/base-nova/protoform/lib/utils';

function AspectRatio({
  ratio,
  className,
  ...props
}: React.ComponentProps<'div'> & {
  ratio: number;
}) {
  const ratioStyle: CSSProperties & Record<`--${string}`, string | number | undefined> = {
    '--ratio': ratio,
  };
  return (
    <div
      className={cn('relative aspect-(--ratio)', className)}
      data-slot="aspect-ratio"
      style={ratioStyle}
      {...props}
    />
  );
}

export { AspectRatio };

