    color: 'var(--popover-foreground)',
    borderColor: 'var(--border)',
  },
  '.cm-tooltip-lint': { maxWidth: 'min(24rem, calc(100vw - 2rem))', whiteSpace: 'normal', overflowWrap: 'anywhere' },
  '.cm-lintRange-error': {
