'use client';

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { JSONEditorLayout } from '@/components/ui/shared/control-layouts';
import { Text } from '@/components/ui/shared/typography';
import type { JSONFieldControls } from './json-controls';
import type { JSONValue } from './json-model';
import { parseJson } from './json-model';

const JSONCodeEditor = React.lazy(() =>
  import('./json-code-editor').then((module) => ({ default: module.JSONCodeEditor }))
);

const editorLoading = (
  <div className="min-h-25 p-2.5">
    <Text role="status" variant="small">
      Loading JSON editor…
    </Text>
  </div>
);

interface JSONEditorProps {
  controls: JSONFieldControls;
  error?: string | undefined;
  id?: string | undefined;
  label: string;
  onChange: (value: JSONValue) => void;
  onDraftChange?: (value: string) => void;
  value: string;
}

const JSONEditor = ({ controls, value, onChange, error: externalError, label, onDraftChange, id }: JSONEditorProps) => {
  'use no memo';

  const { Textarea } = controls;

  const [editorContent, setEditorContent] = useState(value);
  const [internalError, setInternalError] = useState<string | undefined>(undefined);
  const generatedId = React.useId();
  const editorId = id ?? generatedId;
  const containerRef = useRef<HTMLDivElement>(null);
  const lastPublishedTextRef = useRef<string | undefined>(undefined);
  const previousValueRef = useRef(value);

  useEffect(
    function synchronizeEditor() {
      if (previousValueRef.current === value) {
        return;
      }
      previousValueRef.current = value;
      if (value !== lastPublishedTextRef.current && value !== editorContent) {
        setEditorContent(value);
        setInternalError(undefined);
      }
      lastPublishedTextRef.current = undefined;
    },
    [value, editorContent]
  );

  const handleEditorChange = (newContent: string) => {
    setEditorContent(newContent);
    onDraftChange?.(newContent);
    let parsed: JSONValue;
    try {
      parsed = parseJson(newContent);
    } catch (error) {
      setInternalError(`Invalid JSON. ${error instanceof Error ? error.message : 'Check the syntax.'}`);
      return;
    }
    lastPublishedTextRef.current = JSON.stringify(parsed, null, 2);
    setInternalError(undefined);
    onChange(parsed);
  };

  const displayError = internalError ?? externalError;
  const errorId = `${editorId}-error`;
  const focusEditor = () => containerRef.current?.querySelector<HTMLElement>('[role="textbox"]')?.focus();

  useLayoutEffect(
    function synchronizeTextareaValidity() {
      const textarea = containerRef.current?.querySelector('textarea');
      if (!textarea) {
        return;
      }
      textarea.setCustomValidity(displayError ?? '');
      if (displayError !== undefined && displayError !== '') {
        textarea.setAttribute('aria-invalid', 'true');
        textarea.setAttribute('aria-describedby', errorId);
      } else {
        textarea.removeAttribute('aria-invalid');
        textarea.removeAttribute('aria-describedby');
      }
    },
    [displayError, errorId]
  );

  const input = (
    <Textarea
      aria-hidden="true"
      className="sr-only"
      id={editorId}
      onChange={(event) => handleEditorChange(event.currentTarget.value)}
      onFocus={focusEditor}
      onInvalid={(event) => {
        event.preventDefault();
        focusEditor();
      }}
      tabIndex={-1}
      value={editorContent}
    />
  );

  const editor = (
    <JSONCodeEditor
      error={displayError}
      errorId={errorId}
      id={editorId}
      label={label}
      onChange={handleEditorChange}
      value={editorContent}
    />
  );
  const feedback =
    displayError !== undefined && displayError !== '' ? (
      <Text className="mt-1 text-destructive" id={errorId} role="alert" variant="small">
        {displayError}
      </Text>
    ) : null;
  return (
    <JSONEditorLayout
      containerRef={containerRef}
      editor={editor}
      editorId={editorId}
      error={displayError}
      feedback={feedback}
      input={input}
      label={label}
      loading={editorLoading}
    />
  );
};

export { JSONEditor };

'use client';

import { Braces, FileEdit, SpellCheck, Trash2 } from 'lucide-react';
import React, { useEffect, useRef, useState } from 'react';
import {
  JSONArrayCardLayout,
  JSONArrayLayout,
  JSONPropertiesLayout,
  JSONPropertyLayout,
} from '@/components/ui/shared/control-layouts';
import { CopyButton } from '@/components/ui/shared/copy-button';
import { Heading, Text } from '@/components/ui/shared/typography';
import { cn } from '@/registry/base-nova/protoform/lib/utils';
import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';
import type { ComboboxOption, JSONFieldControls } from './json-controls';
import { JSONEditor } from './json-editor';
import type { CustomFieldConfig, JSONSchemaType, JSONValue } from './json-model';
import {
  EMPTY_CUSTOM_FIELDS,
  formatNumericValue,
  getArrayItemDefault,
  getJSONProperty,
  getStringInputType,
  initialJSONText,
  isJSONOnlySchema,
  isSimpleObject,
  jsonEditorLabel,
  parseJson,
  TRAILING_S_REGEX,
  updateValueAtPath,
  withJSONDefault,
} from './json-model';

export type JSONFieldProps = {
  schema: JSONSchemaType;
  value: JSONValue;
  onChange: (value: JSONValue) => void;
  onBlur?: () => void;
  label?: string;
  maxDepth?: number;
  showPlaceholder?: boolean;
  customFields?: CustomFieldConfig[];
  className?: string;
} & Omit<React.ComponentProps<'div'>, 'onChange'> &
  SharedProps;

function JSONField({
  controls,
  deferJSONMode = false,
  schema,
  value,
  onChange,
  onBlur,
  maxDepth = 3,
  showPlaceholder = true,
  customFields = EMPTY_CUSTOM_FIELDS,
  className,
  label,
  id,
  testId,
  ref,
  ...rest
}: JSONFieldProps & { controls: JSONFieldControls; deferJSONMode?: boolean }) {
  'use no memo';

  const { Badge, Button, Combobox: OptionCombobox, Input, Label, notify } = controls;

  const instanceId = React.useId();
  const containerRef = useRef<HTMLDivElement>(null);
  const controlId = (path: string[]) => `${instanceId}-${encodeURIComponent(JSON.stringify(path))}`;
  const controlLabel = (path: string[]) => [label, ...path].filter(Boolean).join('.') || 'Value';
  const [isJSONMode, setIsJSONMode] = useState(false);
  const [jsonError, setJSONError] = useState<string | undefined>(undefined);
  const [optionError, setOptionError] = useState<string | undefined>(undefined);

  const [rawJSONValue, setRawJSONValue] = useState<string>(() => initialJSONText(value, schema, showPlaceholder));

  const lastPublishedValueRef = useRef(value);

  const publishValue = (parsed: JSONValue) => {
    lastPublishedValueRef.current = parsed;
    onChange(parsed);
    setJSONError(undefined);
  };

  useEffect(
    function synchronizeExternalValue() {
      if (Object.is(value, lastPublishedValueRef.current)) {
        return;
      }
      lastPublishedValueRef.current = value;
      setJSONError(undefined);
      setRawJSONValue(initialJSONText(value, schema, showPlaceholder));
    },
    [value, schema, showPlaceholder]
  );

  const handleSwitchToFormMode = () => {
    const invalidEditor = [...(containerRef.current?.querySelectorAll('textarea') ?? [])].find(
      (textarea) => !textarea.checkValidity()
    );
    if (invalidEditor !== undefined) {
      invalidEditor.reportValidity();
      return;
    }
    if (isJSONMode === true) {
      let parsed: JSONValue;
      try {
        parsed = parseJson(rawJSONValue);
      } catch (error) {
        setJSONError(error instanceof Error ? error.message : 'Invalid JSON');
        return;
      }
      publishValue(parsed);
      setIsJSONMode(false);
    } else {
      setRawJSONValue(initialJSONText(value, schema, showPlaceholder));
      setIsJSONMode(true);
    }
  };

  const formatJSON = () => {
    let parsed: JSONValue;
    try {
      const jsonStr = rawJSONValue.trim();
      if (!jsonStr) {
        return;
      }
      parsed = parseJson(jsonStr);
    } catch (error) {
      setJSONError(error instanceof Error ? error.message : 'Invalid JSON');
      return;
    }
    setRawJSONValue(JSON.stringify(parsed, null, 2));
    publishValue(parsed);
  };

  const renderFormFields = (
    propSchema: JSONSchemaType,
    currentValue: JSONValue,
    path: string[] = [],
    depth = 0,
    parentSchema?: JSONSchemaType,
    propertyName?: string
  ): React.ReactNode => {
    if (depth >= maxDepth && (propSchema.type === 'object' || propSchema.type === 'array')) {
      const emptyValue = propSchema.type === 'array' ? [] : {};
      return (
        <JSONEditor
          controls={controls}
          label={jsonEditorLabel(propertyName, path)}
          onChange={(parsed) => handleFieldChange(path, parsed)}
          value={JSON.stringify(withJSONDefault(currentValue, emptyValue), null, 2)}
        />
      );
    }

    const isRequired = parentSchema?.required?.includes(propertyName ?? '') ?? false;

    let fieldType = propSchema.type;
    if (Array.isArray(fieldType)) {
      fieldType = fieldType.find((t) => t !== 'null') ?? fieldType[0];
    }

    switch (fieldType) {
      case 'string': {
        const customFieldConfig = customFields.find((field) => field.fieldName === propertyName);
        if (customFieldConfig !== undefined) {
          const effectiveValue = (() => {
            if (
              customFieldConfig.options.length === 1 &&
              !(currentValue !== undefined && currentValue !== null && Boolean(currentValue))
            ) {
              return customFieldConfig.options[0]?.value ?? '';
            }
            return typeof currentValue === 'string' ? currentValue : '';
          })();

          return (
            <OptionCombobox
              aria-label={controlLabel(path)}
              creatable
              id={controlId(path)}
              onChange={(val) => {
                if (val || isRequired) {
                  handleFieldChange(path, val);
                } else {
                  handleFieldChange(path, undefined);
                }
              }}
              onCreateOption={(newValue) => {
                if (customFieldConfig.onCreateOption) {
                  customFieldConfig
                    .onCreateOption(newValue, path, handleFieldChange)
                    .then(() => setOptionError(undefined))
                    .catch((error: unknown) => {
                      setOptionError(error instanceof Error ? error.message : 'Could not create the option.');
                    });
                } else {
                  const newOption = { label: newValue, value: newValue };
                  customFieldConfig.options.push(newOption);
                  handleFieldChange(path, newValue);
                }
              }}
              options={customFieldConfig.options}
              placeholder={customFieldConfig.placeholder || 'Select an option...'}
              value={effectiveValue ?? ''}
            />
          );
        }

        if (
          propSchema.oneOf?.every(
            (option): option is typeof option & { const: string; title: string } =>
              typeof option.const === 'string' && typeof option.title === 'string'
          ) === true
        ) {
          const oneOfOptions: ComboboxOption[] = propSchema.oneOf.map((option) => ({
            label: option.title,
            value: option.const,
          }));

          return (
            <OptionCombobox
              aria-label={controlLabel(path)}
              creatable
              id={controlId(path)}
              onChange={(val) => {
                if (val || isRequired) {
                  handleFieldChange(path, val);
                } else {
                  handleFieldChange(path, undefined);
                }
              }}
              onCreateOption={(newValue) => {
                const newOption = { label: newValue, value: newValue };
                oneOfOptions.push(newOption);
                handleFieldChange(path, newValue);
              }}
              options={oneOfOptions}
              placeholder="Select an option…"
              value={typeof currentValue === 'string' ? currentValue : ''}
            />
          );
        }

        if (propSchema.enum) {
          const enumOptions: ComboboxOption[] = propSchema.enum.map((option) => ({
            label: option,
            value: option,
          }));

          return (
            <OptionCombobox
              aria-label={controlLabel(path)}
              creatable
              id={controlId(path)}
              onChange={(val) => {
                if (val || isRequired) {
                  handleFieldChange(path, val);
                } else {
                  handleFieldChange(path, undefined);
                }
              }}
              onCreateOption={(newValue) => {
                const newOption = { label: newValue, value: newValue };
                enumOptions.push(newOption);
                handleFieldChange(path, newValue);
              }}
              options={enumOptions}
              placeholder="Select an option…"
              value={typeof currentValue === 'string' ? currentValue : ''}
            />
          );
        }

        const inputType = getStringInputType(propSchema.format);

        return (
          <Input
            aria-label={controlLabel(path)}
            id={controlId(path)}
            maxLength={propSchema.maxLength}
            minLength={propSchema.minLength}
            onChange={(e) => {
              const val = e.target.value;
              handleFieldChange(path, val);
            }}
            pattern={propSchema.pattern}
            placeholder={propSchema.description}
            required={isRequired}
            type={inputType}
            value={typeof currentValue === 'string' ? currentValue : ''}
          />
        );
      }

      case 'number':
        return (
          <Input
            aria-label={controlLabel(path)}
            id={controlId(path)}
            max={propSchema.maximum}
            min={propSchema.minimum}
            onChange={(e) => {
              const val = e.target.value;
              if (val || isRequired) {
                const num = Number(val);
                if (!Number.isNaN(num)) {
                  handleFieldChange(path, num);
                }
              } else {
                handleFieldChange(path, undefined);
              }
            }}
            placeholder={propSchema.description}
            required={isRequired}
            type="number"
            value={typeof currentValue === 'number' ? formatNumericValue(currentValue) : ''}
          />
        );

      case 'integer':
        return (
          <Input
            aria-label={controlLabel(path)}
            id={controlId(path)}
            max={propSchema.maximum}
            min={propSchema.minimum}
            onChange={(e) => {
              const val = e.target.value;
              if (val || isRequired) {
                const num = Number(val);
                if (!Number.isNaN(num) && Number.isInteger(num)) {
                  handleFieldChange(path, num);
                }
              } else {
                handleFieldChange(path, undefined);
              }
            }}
            placeholder={propSchema.description}
            required={isRequired}
            step="1"
            type="number"
            value={typeof currentValue === 'number' ? formatNumericValue(currentValue) : ''}
          />
        );

      case 'boolean':
        return (
          <Input
            aria-label={controlLabel(path)}
            checked={typeof currentValue === 'boolean' ? currentValue : false}
            className="size-4"
            id={controlId(path)}
            onChange={(e) => handleFieldChange(path, e.target.checked)}
            required={isRequired}
            type="checkbox"
          />
        );
      case 'null':
        return null;
      case 'object': {
        if (!propSchema.properties) {
          return (
            <JSONEditor
              controls={controls}
              label={jsonEditorLabel(propertyName, path)}
              onChange={(parsed) => handleFieldChange(path, parsed)}
              value={JSON.stringify(withJSONDefault(currentValue, {}), null, 2)}
            />
          );
        }

        const requiredFields = new Set(propSchema.required);

        const fields = Object.entries(propSchema.properties).map(([key, subSchema]) => {
          const caption = (
            <>
              <Label htmlFor={controlId([...path, key])} variant="strong">
                {key}
                {requiredFields.has(key) && <span className="ml-1 text-destructive">*</span>}
              </Label>
              <Badge size="sm" variant="outline">
                {subSchema.type ?? 'unknown'}
              </Badge>
            </>
          );
          return (
            <JSONPropertyLayout caption={caption} key={key}>
              {renderFormFields(
                subSchema,
                getJSONProperty(currentValue, key),
                [...path, key],
                depth + 1,
                propSchema,
                key
              )}
            </JSONPropertyLayout>
          );
        });
        return <JSONPropertiesLayout>{fields}</JSONPropertiesLayout>;
      }
      case 'array': {
        let arrayValue = Array.isArray(currentValue) ? currentValue : [];
        const itemSchema = propSchema.items;
        if (!itemSchema) {
          return null;
        }

        if (arrayValue.length === 0) {
          const defaultValue = getArrayItemDefault(itemSchema);
          arrayValue = [defaultValue];
        }

        if (isSimpleObject(itemSchema)) {
          const requiredItemFields = new Set(itemSchema.required);
          const description =
            propSchema.description !== undefined && propSchema.description !== '' ? (
              <Text className="text-muted-foreground" variant="small">
                {propSchema.description}
              </Text>
            ) : null;
          const cards = arrayValue.map((item, index) => {
            const itemTypeName =
              [itemSchema.title, itemSchema.description, propertyName?.replace(TRAILING_S_REGEX, '')].find(Boolean) ??
              'Item';
            const itemDisplayName = itemTypeName.charAt(0).toUpperCase() + itemTypeName.slice(1);
            const title = (
              <Heading className="text-sm" level={4}>
                {itemDisplayName} #{index + 1}
              </Heading>
            );
            const removeAction = (
              <Button
                aria-label={`Remove ${controlLabel([...path, String(index)])}`}
                className={arrayValue.length <= 1 ? 'invisible' : ''}
                disabled={arrayValue.length <= 1}
                onClick={() => {
                  const newArray = [...arrayValue];
                  newArray.splice(index, 1);
                  handleFieldChange(path, newArray);
                }}
                size="sm"
                type="button"
                variant="outline"
              >
                <Trash2 className="size-4" />
              </Button>
            );
            const fields =
              itemSchema.type === 'object' && itemSchema.properties
                ? Object.entries(itemSchema.properties).map(([key, subSchema]) => {
                    const caption = (
                      <>
                        <Label htmlFor={controlId([...path, String(index), key])} variant="strong">
                          {key}
                        </Label>
                        <Badge size="sm" variant="outline">
                          {subSchema.type ?? 'unknown'}
                        </Badge>
                        {requiredItemFields.has(key) && <span className="ml-1 text-destructive">*</span>}
                      </>
                    );
                    return (
                      <JSONPropertyLayout arrayItem caption={caption} key={key}>
                        {renderFormFields(
                          subSchema,
                          getJSONProperty(item, key),
                          [...path, index.toString(), key],
                          depth + 1,
                          itemSchema,
                          key
                        )}
                      </JSONPropertyLayout>
                    );
                  })
                : renderFormFields(itemSchema, item, [...path, index.toString()], depth + 1);
            return (
              <JSONArrayCardLayout action={removeAction} key={index} title={title}>
                {fields}
              </JSONArrayCardLayout>
            );
          });
          const addAction = (
            <Button
              className="w-full"
              onClick={() => {
                const defaultValue = getArrayItemDefault(itemSchema);
                handleFieldChange(path, [...arrayValue, defaultValue]);
              }}
              size="sm"
              type="button"
              variant="dashed"
            >
              + Add{' '}
              {[itemSchema.title, itemSchema.description, propertyName?.replace(TRAILING_S_REGEX, '')].find(Boolean) ??
                'Item'}
            </Button>
          );
          return (
            <JSONArrayLayout action={addAction} description={description}>
              {cards}
            </JSONArrayLayout>
          );
        }

        return (
          <JSONEditor
            controls={controls}
            error={jsonError}
            label={jsonEditorLabel(propertyName, path)}
            onChange={(parsed) => handleFieldChange(path, parsed)}
            value={JSON.stringify(withJSONDefault(currentValue, []), null, 2)}
          />
        );
      }
      default:
        return null;
    }
  };

  const handleFieldChange = (path: string[], fieldValue: JSONValue) => {
    if (path.length === 0) {
      onChange(fieldValue);
      return;
    }

    try {
      const newValue = updateValueAtPath(value, path, fieldValue);
      onChange(newValue);
    } catch {
      onChange(value);
    }
  };
  const handleFieldChangeEffect = React.useEffectEvent(handleFieldChange);

  const shouldUseJSONMode = isJSONOnlySchema(schema);

  if (deferJSONMode !== true && shouldUseJSONMode && isJSONMode !== true) {
    setIsJSONMode(true);
  }

  useEffect(() => {
    if (shouldUseJSONMode && isJSONMode !== true) {
      setIsJSONMode(true);
    }
  }, [shouldUseJSONMode, isJSONMode]);

  useEffect(() => {
    const initializeArrayDefaults = (currentSchema: JSONSchemaType, currentValue: JSONValue, path: string[] = []) => {
      if (currentSchema.type === 'array' && currentSchema.items) {
        const arrayValue = Array.isArray(currentValue) ? currentValue : [];
        if (arrayValue.length === 0) {
          const defaultValue = getArrayItemDefault(currentSchema.items);
          const newValue = updateValueAtPath(value, path, [defaultValue]);
          onChange(newValue);
        }
      } else if (currentSchema.type === 'object' && currentSchema.properties) {
        for (const [key, subSchema] of Object.entries(currentSchema.properties)) {
          const subValue = getJSONProperty(currentValue, key);
          initializeArrayDefaults(subSchema, subValue, [...path, key]);
        }
      }
    };

    if (value !== undefined && isJSONMode !== true) {
      initializeArrayDefaults(schema, value);
    }
  }, [schema, value, onChange, isJSONMode]);

  useEffect(
    function synchronizeCustomFields() {
      const customFieldsByName = new Map(customFields.map((field) => [field.fieldName, field]));
      const syncAutoSelections = (currentSchema: JSONSchemaType, currentValue: JSONValue, path: string[] = []) => {
        if (currentSchema.type === 'object' && currentSchema.properties) {
          for (const [key, subSchema] of Object.entries(currentSchema.properties)) {
            const subValue = getJSONProperty(currentValue, key);
            const customFieldConfig = customFieldsByName.get(key);

            if (
              customFieldConfig?.options.length === 1 &&
              !(subValue !== undefined && subValue !== null && Boolean(subValue))
            ) {
              const autoSelectedValue = customFieldConfig.options[0]?.value ?? '';
              handleFieldChangeEffect([...path, key], autoSelectedValue);
            }

            syncAutoSelections(subSchema, subValue, [...path, key]);
          }
        }
      };

      if (value !== undefined && isJSONMode !== true && customFieldsByName.size > 0) {
        syncAutoSelections(schema, value);
      }
    },
    [schema, value, customFields, isJSONMode]
  );

  return (
    <div
      className={cn('space-y-4', className)}
      data-testid={testId}
      onBlur={onBlur}
      ref={(element) => {
        containerRef.current = element;
        if (typeof ref === 'function') {
          return ref(element);
        }
        if (ref) {
          ref.current = element;
        }
      }}
      {...rest}
    >
      <div className="flex flex-wrap justify-end gap-2">
        {isJSONMode === true ? (
          <>
            <CopyButton
              content={JSON.stringify(value, null, 2)}
              onCopy={() =>
                notify({
                  description: 'The JSON data was copied to your clipboard.',
                  title: 'JSON copied',
                  type: 'success',
                })
              }
              size="sm"
              type="button"
              variant="outline"
            >
              Copy JSON
            </CopyButton>
            <Button onClick={formatJSON} size="sm" type="button" variant="outline">
              <SpellCheck className="size-4" />
              Format JSON
            </Button>
          </>
        ) : null}

        <Button onClick={handleSwitchToFormMode} size="sm" type="button" variant="outline">
          {isJSONMode === true ? (
            <>
              <FileEdit className="size-4" />
              Switch to Form
            </>
          ) : (
            <>
              <Braces className="size-4" />
              Switch to JSON
            </>
          )}
        </Button>
      </div>

      {isJSONMode === false && (optionError ?? jsonError) !== undefined ? (
        <Text className="text-destructive" role="alert">
          {optionError ?? jsonError}
        </Text>
      ) : null}
      {isJSONMode === true ? (
        <JSONEditor
          controls={controls}
          error={jsonError}
          id={id}
          label={label !== undefined && label !== '' ? `${label} JSON` : 'JSON value'}
          onChange={publishValue}
          onDraftChange={setRawJSONValue}
          value={rawJSONValue}
        />
      ) : (
        renderFormFields(schema, value)
      )}
    </div>
  );
}

export type { CustomFieldConfig, JSONObject, JSONSchemaConst, JSONSchemaType, JSONValue } from './json-model';
export { JSONField };

export function formatNumericValue(value: number) {
  return value.toString();
}

function isJsonValue(value: unknown): value is JSONValue {
  if (value === null || typeof value === 'string' || typeof value === 'boolean' || typeof value === 'number') {
    return true;
  }
  if (Array.isArray(value)) {
    return value.every(isJsonValue);
  }
  return typeof value === 'object' && Object.values(value).every(isJsonValue);
}

export function parseJson(source: string): JSONValue {
  const value: unknown = JSON.parse(source);
  if (!isJsonValue(value)) {
    throw new TypeError('Invalid JSON value');
  }
  return value;
}

export const TRAILING_S_REGEX = /s$/u;

export function jsonEditorLabel(propertyName: string | undefined, path: string[]): string {
  const name = propertyName ?? path.at(-1) ?? 'value';
  return `${name.charAt(0).toUpperCase()}${name.slice(1)} JSON`;
}

export interface CustomFieldConfig {
  fieldName: string;
  onCreateOption?: (
    newValue: string,
    path: string[],
    handleFieldChange: (path: string[], value: JSONValue) => void
  ) => Promise<void>;
  options: { value: string; label: string }[];
  placeholder?: string;
}

export const EMPTY_CUSTOM_FIELDS: CustomFieldConfig[] = [];

const SIMPLE_JSON_TYPES = new Set(['string', 'number', 'integer', 'boolean', 'null']);

export function getJSONProperty(value: JSONValue, key: string): JSONValue {
  return typeof value === 'object' && value !== null && !Array.isArray(value) ? value[key] : undefined;
}

export function withJSONDefault(value: JSONValue, fallback: JSONValue): JSONValue {
  if (value === undefined) {
    return fallback;
  }
  return value;
}

const isTypeSupported = (type: JSONSchemaType['type'], supportedTypes: ReadonlySet<string>): boolean => {
  if (Array.isArray(type)) {
    return type.every((t) => supportedTypes.has(t));
  }
  return typeof type === 'string' && supportedTypes.has(type);
};

export const isSimpleObject = (schema: JSONSchemaType): boolean => {
  if (schema.type !== undefined && isTypeSupported(schema.type, SIMPLE_JSON_TYPES)) {
    return true;
  }
  if (schema.type === 'object') {
    return schema.properties !== undefined && Object.keys(schema.properties).length > 0;
  }
  if (schema.type === 'array') {
    return Boolean(schema.items);
  }
  return false;
};

export function getStringInputType(format: string | undefined) {
  switch (format) {
    case 'email':
      return 'email';
    case 'uri':
      return 'url';
    case 'date':
      return 'date';
    case 'date-time':
      return 'datetime-local';
    default:
      return 'text';
  }
}

export const getArrayItemDefault = (schema: JSONSchemaType): JSONValue => {
  if ('default' in schema && schema.default !== undefined) {
    return schema.default;
  }

  switch (schema.type) {
    case 'string':
      return '';
    case 'number':
    case 'integer':
      return 0;
    case 'boolean':
      return false;
    case 'array':
      return [];
    case 'object':
      return {};
    case 'null':
      return null;
    default:
      return null;
  }
};

const generateExampleData = (schema: JSONSchemaType): JSONValue => {
  if ('default' in schema && schema.default !== undefined) {
    return schema.default;
  }

  switch (schema.type) {
    case 'string': {
      const example = schema.examples?.[0];
      const hasExample = Boolean(example);
      return hasExample ? example : '';
    }
    case 'number':
    case 'integer': {
      const example = schema.examples?.[0];
      const hasExample = Boolean(example);
      return hasExample ? example : 42;
    }
    case 'boolean':
      return true;
    case 'array':
      if (schema.items) {
        return [generateExampleData(schema.items)];
      }
      return [];
    case 'object':
      if (schema.properties) {
        const result: Record<string, JSONValue> = {};
        for (const [key, propSchema] of Object.entries(schema.properties)) {
          result[key] = generateExampleData(propSchema);
        }
        return result;
      }
      return {};
    case 'null':
      return null;
    default:
      return null;
  }
};

const hasEmptyValues = (value: JSONValue, schema: JSONSchemaType): boolean => {
  if (value === undefined) {
    return true;
  }

  if (schema.type === 'object' && typeof value === 'object' && value !== null && !Array.isArray(value)) {
    const obj = value as Record<string, JSONValue>;
    if (Object.keys(obj).length === 0) {
      return true;
    }

    if (schema.properties) {
      return Object.entries(schema.properties).every(([key, propSchema]) => {
        const val = obj[key];
        const subSchema = propSchema;

        if (val === undefined) {
          return true;
        }
        if (subSchema.type === 'string' && val === '') {
          return true;
        }
        if (subSchema.type === 'array' && Array.isArray(val) && val.length === 0) {
          return true;
        }
        if (subSchema.type === 'object' && hasEmptyValues(val, subSchema)) {
          return true;
        }

        return false;
      });
    }
  }

  if (schema.type === 'array' && Array.isArray(value)) {
    return value.length === 0;
  }

  return false;
};

export function isJSONOnlySchema(schema: JSONSchemaType): boolean {
  return (
    (schema.type === 'object' && (!schema.properties || Object.keys(schema.properties).length === 0)) ||
    (schema.type === 'array' && !schema.items)
  );
}

export function initialJSONText(value: JSONValue, schema: JSONSchemaType, showPlaceholder: boolean): string {
  if (showPlaceholder === true && hasEmptyValues(value, schema)) {
    return JSON.stringify(generateExampleData(schema), null, 2);
  }
  if (value !== undefined) {
    return JSON.stringify(value, null, 2);
  }
  return schema.type === 'array' ? '[]' : '{}';
}

export type JSONValue = string | number | boolean | null | undefined | JSONValue[] | { [key: string]: JSONValue };

export interface JSONSchemaConst {
  const: JSONValue;
  description?: string;
  title?: string;
}

export interface JSONSchemaType {
  anyOf?: (JSONSchemaType | JSONSchemaConst)[];
  const?: JSONValue;
  default?: JSONValue;
  description?: string;
  enum?: string[];
  examples?: JSONValue[];
  format?: string;
  items?: JSONSchemaType;
  maximum?: number;
  maxLength?: number;
  minimum?: number;
  minLength?: number;
  oneOf?: (JSONSchemaType | JSONSchemaConst)[];
  pattern?: string;
  properties?: Record<string, JSONSchemaType>;
  required?: string[];
  title?: string;
  type?:
    | 'string'
    | 'number'
    | 'integer'
    | 'boolean'
    | 'array'
    | 'object'
    | 'null'
    | ('string' | 'number' | 'integer' | 'boolean' | 'array' | 'object' | 'null')[];
}

export type JSONObject = Record<string, JSONValue>;

export function updateValueAtPath(obj: JSONValue, path: string[], value: JSONValue): JSONValue {
  if (path.length === 0) {
    return value;
  }

  let mutableObj = obj;
  if (obj === null || obj === undefined) {
    mutableObj = Number.isNaN(Number(path[0])) ? {} : [];
  }

  if (Array.isArray(mutableObj)) {
    return updateArray(mutableObj, path, value);
  }
  if (typeof mutableObj === 'object' && mutableObj !== null) {
    return updateObject(mutableObj, path, value);
  }
  return mutableObj;
}

function updateArray(array: JSONValue[], path: string[], value: JSONValue): JSONValue[] {
  const [index, ...restPath] = path;
  const arrayIndex = Number(index);

  if (Number.isNaN(arrayIndex)) {
    return array;
  }

  if (arrayIndex < 0) {
    return array;
  }

  let newArray: JSONValue[] = [];
  for (let i = 0; i < array.length; i += 1) {
    newArray[i] = i in array ? array[i] : null;
  }

  if (arrayIndex >= newArray.length) {
    const extendedArray: JSONValue[] = Array.from({ length: arrayIndex }, () => null);
    for (let i = 0; i < newArray.length; i += 1) {
      extendedArray[i] = newArray[i];
    }
    newArray = extendedArray;
  }

  newArray[arrayIndex] = restPath.length === 0 ? value : updateValueAtPath(newArray[arrayIndex], restPath, value);
  return newArray;
}

function updateObject(obj: JSONObject, path: string[], value: JSONValue): JSONObject {
  const [key, ...restPath] = path;

  if (typeof key !== 'string') {
    return obj;
  }

  const newObj = { ...obj };

  if (restPath.length === 0) {
    newObj[key] = value;
  } else {
    if (!(key in newObj)) {
      newObj[key] = {};
    }
    newObj[key] = updateValueAtPath(newObj[key], restPath, value);
  }
  return newObj;
}

